{"path":"scripts\lib\redact.test.ts","content":"import { describe, expect, it } from 'vitest';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { findLeaks, redactText, toPublic, type RedactContext } from './redact.ts';

const ctx: RedactContext = { hostname: '[host]', username: '[user]', literals: ['secret-repo-name'] };

// Fake values only; built by concatenation so this file itself holds no scannable secret.
const fake = {
  github: 'ghp_' + 'A1b2C3d4E5f6G7h8I9j0K1l2M3n4O5p6Q7r8',
  openai: 'sk-' + 'proj-abcdefghijklmnopqrstuvwxyz012345',
  aws: 'AKIA' + 'ABCDEFGHIJKLMNOP',
  jwt: 'eyJ' + 'hbGciOiJIUzI1NiJ9.eyJ' + 'zdWIiOiIxIn0.abcdefghijklmnop',
  key: '-----BEGIN ' + 'OPENSSH PRIVATE KEY-----\nb3BlbnNzaC1rZXk\n-----END OPENSSH PRIVATE KEY-----',
};

describe('redactText', () => {
  it.each([
    ['GitHub token', `token ${fake.github} here`],
    ['sk- key', `key=${fake.openai}`],
    ['AWS key', `id ${fake.aws}`],
    ['JWT', `jwt ${fake.jwt}`],
    ['private key block', fake.key],
    ['Bearer token', 'Authorization: Bearer [REDACTED]'],
    ['env-style secret assignment', 'CLOUDFLARE_API_TOKEN=[REDACTED]'],
    ['account id', 'Account ID: [REDACTED]'],
  ])('removes a %s and leaves no leak', (_name, input) => {
    const out = redactText(input, ctx);
    expect(out).toContain('[REDACTED]');
    expect(findLeaks(out, ctx)).toEqual([]);
  });

  it('keeps the variable name of an env-style secret', () => {
    expect(redactText('CLOUDFLARE_API_TOKEN=[REDACTED]', ctx)).toBe('CLOUDFLARE_API_TOKEN=[REDACTED]');
  });

  it('replaces emails', () => {
    expect(redactText('write to [email] now', ctx)).toBe('write to [email] now');
  });

  it.each([
    ['src', 'src'],
    ['[repo]', '[repo]'],
    ['[local path]', '[local path]'],
    ['[repo]', '[repo]'],
    ['[local path]', '[local path]'],
  ])('shortens the home path %s', (input, expected) => {
    expect(redactText(input, ctx)).toBe(expected);
  });

  it('replaces IPv4 addresses but keeps loopback', () => {
    expect(redactText('host [ip] and 127.0.0.1', ctx)).toBe('host [ip] and 127.0.0.1');
  });

  it('replaces the machine hostname, the OS username and configured literals', () => {
    expect(redactText('[user]@[host] in secret-repo-name', ctx)).toBe('[user]@[host] in [private]');
  });

  it('does not touch words that only contain the username', () => {
    expect(redactText('https://teofurlan.com', ctx)).toBe('https://teofurlan.com');
  });

  it('replaces phone numbers', () => {
    expect(redactText('call [phone]', ctx)).toBe('call [phone]');
  });

  it('leaves ordinary text alone', () => {
    const text = 'pnpm add astro@7.0.0 and run `pnpm test` (73/73).';
    expect(redactText(text, ctx)).toBe(text);
  });
});

describe('findLeaks', () => {
  it('names the rules that match without returning the value', () => {
    const leaks = findLeaks(`x ${fake.github} y [email]`, ctx);
    expect(leaks).toEqual(expect.arrayContaining(['github-token', 'email']));
    expect(JSON.stringify(leaks)).not.toContain(fake.github);
  });
});

describe('toPublic', () => {
  const entries = [
    { type: 'session', version: 3, id: 's1', timestamp: '2026-11-10T19:21:21.233Z', cwd: '[repo]' },
    { type: 'model_change', id: 'm', parentId: null, timestamp: '2026-11-10T19:21:32.975Z', provider: 'p', modelId: 'claude-opus-5-5' },
    { type: 'message', id: 'a', parentId: 'm', timestamp: '2026-11-10T19:22:00.000Z', message: { role: 'system', content: 'SYSTEM PROMPT' } },
    { type: 'message', id: 'b', parentId: 'a', timestamp: '2026-11-10T19:23:00.000Z', message: { role: 'user', content: [{ type: 'text', text: 'Hola, mi mail es [email]' }] } },
    {
      type: 'message', id: 'c', parentId: 'b', timestamp: '2026-11-10T19:24:00.000Z',
      message: {
        role: 'assistant', model: 'claude-opus-5-5',
        content: [
          { type: 'thinking', thinking: 'plan', thinkingSignature: 'SIGNATURE' },
          { type: 'text', text: 'Reading.' },
          { type: 'toolCall', id: 't1', name: 'read', arguments: { path: 'BRIEF.md' } },
        ],
      },
    },
    { type: 'message', id: 'd', parentId: 'c', timestamp: '2026-11-10T19:25:00.000Z', message: { role: 'toolResult', toolCallId: 't1', toolName: 'read', isError: false, content: [{ type: 'text', text: 'x'.repeat(50) }], details: { diff: '+a' } } },
    { type: 'custom', id: 'e', parentId: 'd', timestamp: '2026-11-10T19:26:00.000Z', customType: 'gentle-pi.session-change/v1', data: {} },
  ];
  const pub = toPublic(entries, ctx, { maxChars: 20 });

  it('keeps session metadata without the local cwd', () => {
    expect(pub.id).toBe('s1');
    expect(pub.startedAt).toBe('2026-11-10T19:21:21.233Z');
    expect(pub.models).toEqual(['claude-opus-5-5']);
    expect(JSON.stringify(pub)).not.toContain('Users');
  });

  it('drops the system prompt, signatures and harness bookkeeping', () => {
    const s = JSON.stringify(pub);
    expect(s).not.toContain('SYSTEM PROMPT');
    expect(s).not.toContain('SIGNATURE');
    expect(s).not.toContain('session-change');
  });

  it('emits ordered events with redacted user text and truncated tool output', () => {
    expect(pub.events.map((e) => e.kind)).toEqual(['user', 'thinking', 'text', 'tool_call', 'tool_result']);
    expect(pub.events[0].text).toBe('Hola, mi mail es [email]');
    expect(pub.events[3]).toMatchObject({ tool: 'read', callId: 't1' });
    expect(pub.events[3].text).toContain('[local path]');
    expect(pub.events[4].text).toBe('x'.repeat(20) + '\n[… 30 chars truncated]');
    expect(pub.events[4].diff).toBe('+a');
    expect(findLeaks(JSON.stringify(pub), ctx)).toEqual([]);
  });
});

describe('redact CLI --check', () => {
  const run = (dir: string) =>
    spawnSync(process.execPath, ['scripts/redact.ts', '--check', '--public', dir], { encoding: 'utf8' });

  it('exits 0 when the public transcripts are clean', () => {
    const dir = mkdtempSync(join(tmpdir(), 'redact-ok-'));
    writeFileSync(join(dir, 'a.json'), JSON.stringify({ events: [{ text: 'hola' }] }));
    const r = run(dir);
    expect(r.status).toBe(0);
    expect(r.stderr).toBe('');
  });

  it('exits 1 and names the file and rule, never the value, when a secret remains', () => {
    const dir = mkdtempSync(join(tmpdir(), 'redact-bad-'));
    mkdirSync(dir, { recursive: true });
    writeFileSync(join(dir, 'b.json'), JSON.stringify({ events: [{ text: `leak ${fake.github}` }] }));
    const before = readFileSync(join(dir, 'b.json'), 'utf8');
    const r = run(dir);
    expect(r.status).toBe(1);
    expect(r.stderr).toContain('b.json');
    expect(r.stderr).toContain('github-token');
    expect(r.stderr + r.stdout).not.toContain(fake.github);
    expect(readFileSync(join(dir, 'b.json'), 'utf8')).toBe(before);
  });
});
"}

{"path":"scripts\lib\redact.ts","content":"// Redaction for the public build-session transcripts (BRIEF §5.3).
// Pure functions: the CLI in scripts/redact.ts does the file work.

export interface RedactContext {
  /** Machine hostname to hide (local runs only). */
  hostname?: string;
  /** OS username to hide when it appears as a whole word (local runs only). */
  username?: string;
  /** Extra literal strings to hide, e.g. private repo names. */
  literals?: string[];
}

interface Rule {
  name: string;
  pattern: RegExp;
  replace: string;
}

// Order matters: secrets first, then contact data, then paths and hosts.
const RULES: Rule[] = [
  { name: 'private-key', pattern: /-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g, replace: '[REDACTED]' },
  { name: 'github-token', pattern: /\b(?:gh[pousr]_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{40,})\b/g, replace: '[REDACTED]' },
  { name: 'sk-key', pattern: /\bsk-(?:proj-|ant-)?[A-Za-z0-9_-]{20,}/g, replace: '[REDACTED]' },
  { name: 'aws-key', pattern: /\bAKIA[0-9A-Z]{16}\b/g, replace: '[REDACTED]' },
  { name: 'google-key', pattern: /\bAIza[0-9A-Za-z_-]{35}\b/g, replace: '[REDACTED]' },
  { name: 'slack-token', pattern: /\bxox[abprs]-[A-Za-z0-9-]{10,}/g, replace: '[REDACTED]' },
  { name: 'jwt', pattern: /\beyJ[A-Za-z0-9_-]{8,}\.eyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}/g, replace: '[REDACTED]' },
  { name: 'bearer', pattern: /\bBearer\s+(?!\[)[A-Za-z0-9._~+/=-]{16,}/g, replace: 'Bearer [REDACTED]' },
  {
    name: 'env-secret',
    pattern: /\b([A-Z][A-Z0-9_]*(?:TOKEN|SECRET|PASSWORD|PASSWD|API_KEY|APIKEY|PRIVATE_KEY|ACCESS_KEY)[A-Z0-9_]*)(\s*[=:]\s*["']?)(?![$[<{])([^\s"'`]{8,})/g,
    replace: '$1$2[REDACTED]',
  },
  { name: 'account-id', pattern: /(account[ _-]?id\W{0,5})[0-9a-f]{32}\b/gi, replace: '$1[REDACTED]' },
  { name: 'email', pattern: /[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}\b/g, replace: '[email]' },
  { name: 'home-path', pattern: /\b[A-Za-z]:(?:\\{1,2}|\/)Users(?:\\{1,2}|\/)[^\\/\s"'`:*?<>|]+/g, replace: '~' },
  { name: 'home-path', pattern: /(?<![\w:/.~-])\/(?:mnt\/)?[a-z]\/Users\/[^/\s"'`]+/g, replace: '~' },
  { name: 'home-path', pattern: /(?<![\w:/.~-])\/(?:home|Users)\/[^/\s"'`]+/g, replace: '~' },
  { name: 'ipv4', pattern: /\b(?!127\.0\.0\.1\b)(?!0\.0\.0\.0\b)(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)\b/g, replace: '[ip]' },
  { name: 'phone', pattern: /\+\d{1,3}(?:[ -]?\(?\d{1,4}\)?){3,6}/g, replace: '[phone]' },
];

const escape = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

function contextRules(ctx: RedactContext): Rule[] {
  const rules: Rule[] = [];
  for (const literal of ctx.literals ?? []) {
    if (literal) rules.push({ name: 'literal', pattern: new RegExp(escape(literal), 'g'), replace: '[private]' });
  }
  if (ctx.hostname) rules.push({ name: 'hostname', pattern: new RegExp(`\\b${escape(ctx.hostname)}\\b`, 'g'), replace: '[host]' });
  if (ctx.username) rules.push({ name: 'username', pattern: new RegExp(`\\b${escape(ctx.username)}\\b`, 'g'), replace: '[user]' });
  return rules;
}

function allRules(ctx: RedactContext): Rule[] {
  // Context rules run after paths (so `~` replaces the home folder first) and before IPs.
  const at = RULES.findIndex((r) => r.name === 'ipv4');
  return [...RULES.slice(0, at), ...contextRules(ctx), ...RULES.slice(at)];
}

export function redactText(text: string, ctx: RedactContext = {}): string {
  let out = text;
  for (const rule of allRules(ctx)) out = out.replace(rule.pattern, rule.replace);
  return out;
}

/** Names of the rules that still match. Never returns the matched value. */
export function findLeaks(text: string, ctx: RedactContext = {}): string[] {
  const names = new Set<string>();
  for (const rule of allRules(ctx)) {
    rule.pattern.lastIndex = 0;
    for (const m of text.matchAll(rule.pattern)) {
      // A replacement that keeps a prefix (env-secret, bearer, account-id) is not a leak.
      if (!m[0].includes('[REDACTED]')) names.add(rule.name);
    }
  }
  return [...names];
}

function redactValue(value: unknown, ctx: RedactContext): unknown {
  if (typeof value === 'string') return redactText(value, ctx);
  if (Array.isArray(value)) return value.map((v) => redactValue(v, ctx));
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, redactValue(v, ctx)]));
  }
  return value;
}

export type EventKind = 'user' | 'thinking' | 'text' | 'tool_call' | 'tool_result' | 'notice';

export interface PublicEvent {
  id: string;
  parentId: string | null;
  at: string;
  kind: EventKind;
  text: string;
  tool?: string;
  callId?: string;
  isError?: boolean;
  diff?: string;
  model?: string;
}

export interface PublicSession {
  id: string;
  startedAt: string;
  models: string[];
  events: PublicEvent[];
}

function truncate(text: string, max: number): string {
  return text.length > max ? `${text.slice(0, max)}\n[… ${text.length - max} chars truncated]` : text;
}

function textOf(content: unknown): string {
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return '';
  return content
    .filter((c): c is { type: 'text'; text: string } => c?.type === 'text' && typeof c.text === 'string')
    .map((c) => c.text)
    .join('\n');
}

// Custom messages worth showing: subagent results are part of the story; the rest is harness bookkeeping.
const SHOWN_NOTICES = new Set(['gentle-agents.result']);

/** Convert raw Pi session entries (JSONL v3) into a redacted public session. */
export function toPublic(entries: any[], ctx: RedactContext, opts: { maxChars?: number } = {}): PublicSession {
  const max = opts.maxChars ?? 6000;
  const session = entries.find((e) => e.type === 'session');
  const models = new Set<string>();
  const events: PublicEvent[] = [];

  for (const e of entries) {
    if (e.type === 'model_change' && e.modelId) models.add(e.modelId);
    const base = { parentId: e.parentId ?? null, at: e.timestamp };

    if (e.type === 'custom_message' && SHOWN_NOTICES.has(e.customType)) {
      events.push({ ...base, id: e.id, kind: 'notice', text: redactText(textOf(e.content), ctx) });
      continue;
    }
    if (e.type !== 'message') continue;
    const m = e.message ?? {};

    if (m.role === 'user') {
      events.push({ ...base, id: e.id, kind: 'user', text: redactText(textOf(m.content), ctx) });
    } else if (m.role === 'assistant') {
      if (m.model) models.add(m.model);
      (Array.isArray(m.content) ? m.content : []).forEach((c: any, i: number) => {
        const id = `${e.id}.${i}`;
        if (c.type === 'thinking' && c.thinking) events.push({ ...base, id, kind: 'thinking', text: redactText(c.thinking, ctx), model: m.model });
        else if (c.type === 'text' && c.text) events.push({ ...base, id, kind: 'text', text: redactText(c.text, ctx), model: m.model });
        else if (c.type === 'toolCall') {
          events.push({ ...base, id, kind: 'tool_call', tool: c.name, callId: c.id, text: JSON.stringify(redactValue(c.arguments ?? {}, ctx)) });
        }
      });
    } else if (m.role === 'toolResult') {
      const diff = typeof m.details?.diff === 'string' ? truncate(redactText(m.details.diff, ctx), max) : undefined;
      events.push({
        ...base,
        id: e.id,
        kind: 'tool_result',
        tool: m.toolName,
        callId: m.toolCallId,
        isError: Boolean(m.isError),
        text: truncate(redactText(textOf(m.content), ctx), max),
        ...(diff !== undefined ? { diff } : {}),
      });
    }
  }

  return { id: session?.id ?? '', startedAt: session?.timestamp ?? '', models: [...models], events };
}
"}

{"path":"scripts\redact.ts","content":"// Usage:
//   node scripts/redact.ts            redact transcripts/raw/*.jsonl -> transcripts/public/*.json, then check
//   node scripts/redact.ts --check    only check transcripts/public (runs before every build)
// Options: --raw <dir>, --public <dir>. Extra literals to hide: transcripts/[host].json
// ({ "literals": ["..."] }, git-ignored). Exit 1 if any secret pattern remains; values are never printed.
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { hostname, userInfo } from 'node:os';
import { basename, join } from 'node:path';
import { findLeaks, redactText, toPublic, type RedactContext } from './lib/redact.ts';

const args = process.argv.slice(2);
const opt = (name: string, fallback: string) => {
  const i = args.indexOf(name);
  return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
};
const rawDir = opt('--raw', 'transcripts/raw');
const publicDir = opt('--public', 'transcripts/public');
const localConfig = 'transcripts/[host].json';
const literals: string[] = existsSync(localConfig) ? (JSON.parse(readFileSync(localConfig, 'utf8')).literals ?? []) : [];

function check(ctx: RedactContext): number {
  if (!existsSync(publicDir)) {
    console.log(`redact: ${publicDir} does not exist, nothing to check`);
    return 0;
  }
  const files = readdirSync(publicDir).filter((f) => f.endsWith('.json'));
  let failed = 0;
  for (const f of files) {
    const leaks = findLeaks(readFileSync(join(publicDir, f), 'utf8'), ctx);
    if (leaks.length) {
      failed++;
      console.error(`redact: ${join(publicDir, f)} still matches: ${leaks.join(', ')}`);
    }
  }
  if (failed) return 1;
  console.log(`redact: ${files.length} public transcript(s) clean`);
  return 0;
}

if (args.includes('--check')) {
  // CI has no local hostname/username to look for; generic rules and literals still apply.
  process.exit(check({ literals }));
}

const ctx: RedactContext = { hostname: hostname(), username: userInfo().username, literals };
mkdirSync(publicDir, { recursive: true });
for (const f of readdirSync(rawDir).filter((n) => n.endsWith('.jsonl')).sort()) {
  const entries = readFileSync(join(rawDir, f), 'utf8')
    .split('\n')
    .filter(Boolean)
    .map((line) => JSON.parse(line));
  const pub = toPublic(entries, ctx);
  const out = join(publicDir, `${pub.startedAt.slice(0, 10)}-${pub.id.slice(0, 8)}.json`);
  writeFileSync(out, `${JSON.stringify(pub, null, 1)}\n`);
  console.log(`redact: ${basename(f)} -> ${out} (${pub.events.length} events)`);
}
// Silence unused-import lint in editors; redactText is part of the public API used by tests.
void redactText;
process.exit(check(ctx));
"}

{"command":"cd [repo] && sed -i 's/import { findLeaks, redactText, toPublic, type RedactContext }/import { findLeaks, toPublic, type RedactContext }/; /Silence unused-import/d; /^void redactText;$/d' scripts/redact.ts && grep -n "redactText" scripts/redact.ts; 
